INSERT INTO fc_sbc_fixed VALUES('FC27',32,'RW',NULL,'Yan Diomande',84,'Real Madrid','LALIGA EA SPORTS','Ivory Coast','RW/RM/LM/LW',0,'고정 사실: 사용자 보고(2026-09-26, 인게임 화면) — EA·fut.gg가 주지 않는 축이다. 카드 사실: fut.gg /api/fut/players/v2/27/?name=diomande (2026-09-26 조회)','MEASURED(사용자 확인) — 어느 칸에 고정인지는 사용자가 읽은 값. ⚠️ fut.gg에 같은 선수 카드가 둘이다(Rare 84 eaId 78012 · Ones to Watch 84 eaId 50409660). 클럽·리그·국적·포지션·OVR이 **동일**해 판정 결과가 갈리지 않으므로 ea_item_id를 비워 둔다 — ⛔ 둘 중 하나로 찍어 적으면 확인하지 않은 사실이 된다.','2026-09-26');
